<?php require '_layout.php'; $pdo=db(); $users=[]; if($pdo)try{$users=$pdo->query('SELECT id,name,email,role,active,created_at FROM users ORDER BY id')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){} admin_header('Người dùng','users'); admin_flash(); ?><section class="products-admin"><div class="dashboard-actions"><div><div class="kicker">Phân quyền</div><h2>Người dùng quản trị</h2><p>Quản lý tài khoản được phép truy cập khu vực Admin.</p></div><a class="admin-button" href="user-form.php">+ Thêm người dùng</a></div><?php if(!$pdo): ?><div class="notice error">MySQL chưa kết nối.</div><?php else: ?><div class="product-table users-table"><div class="table-row table-head"><span>Người dùng</span><span>Vai trò</span><span>Trạng thái</span><span>Ngày tạo</span><span></span></div><?php foreach($users as $u): ?><article class="table-row"><div class="admin-product"><span class="avatar"><?=strtoupper(substr($u['name'],0,1))?></span><div><b><?=htmlspecialchars($u['name'])?></b><small><?=htmlspecialchars($u['email'])?></small></div></div><span class="role"><?=$u['role']==='admin'?'Quản trị viên':'Biên tập viên'?></span><span class="visibility <?=$u['active']?'visible':'hidden'?>"><?=$u['active']?'Đang hoạt động':'Đã khoá'?></span><span><?=date('d/m/Y',strtotime($u['created_at']))?></span><div class="table-actions"><a href="user-form.php?id=<?=$u['id']?>">Sửa</a><?php if($u['id'] != (current_admin()['id']??0)): ?><form method="post" action="user-delete.php" onsubmit="return confirm('Xoá người dùng này?')"><input type="hidden" name="id" value="<?=$u['id']?>"><button>Xoá</button></form><?php endif ?></div></article><?php endforeach ?></div><?php endif ?></section><?php admin_footer(); ?>
